const events = Array.isArray($json.body?.events) ? $json.body.events : [];
const event = events.find((item) => item?.type === 'message' && item?.message?.type === 'image');
if (!event) return [];
return [{ json: { event, receivedAt: $json.body?.receivedAt || null } }];

const candidates = [
  $json.text,
  $json.content?.parts?.map((part) => part?.text).filter(Boolean).join('\n'),
  $json.content?.text,
  $json.response?.text,
  $json.output
];
let raw = candidates.find((value) => typeof value === 'string' && value.trim());
if (!raw && typeof $json.content === 'string') raw = $json.content;
if (!raw) throw new Error('Gemini回傳缺少文字內容');
let cleaned = raw.replace(/^\uFEFF/, '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
if (firstBrace >= 0 && lastBrace > firstBrace) cleaned = cleaned.slice(firstBrace, lastBrace + 1);
let schedule;
try { schedule = JSON.parse(cleaned); } catch (error) { throw new Error('Gemini回傳不是有效JSON'); }
if (typeof schedule === 'string') schedule = JSON.parse(schedule);
const headers = Array.isArray(schedule.header_sequence)
  ? schedule.header_sequence.map((value) => String(value || '').replace(/\s+/g, ''))
  : [];
const requiredHeaders = ['上班', '下班', '上班', '下班'];
const hasRequiredHeaderSequence = headers.some((_, index) =>
  requiredHeaders.every((header, offset) => headers[index + offset] === header)
);
if (schedule.is_attendance_sheet !== true || !hasRequiredHeaderSequence) return [];
if (!schedule.date || !Array.isArray(schedule.employees)) throw new Error('下班條缺少日期或員工資料');
return [{ json: schedule }];
